mapper.select:
SELECT t.*, (SELECT pk.name FROM sys_tenant_package pk WHERE pk.id = t.package_id AND pk.is_deleted = 0) AS package_name FROM sys_tenant t WHERE t.is_deleted = 0
AND (t.name LIKE CONCAT('%', #{request.keyword}, '%') OR t.code LIKE CONCAT('%', #{request.keyword}, '%'))
AND t.status = #{request.status}
AND t.package_id = #{request.packageId}
ORDER BY t.${request.safeSortField()} ${request.safeSortOrder()}
ORDER BY t.create_time DESC
